    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, count(*) n FROM abnormal_traces WHERE service_name='recommendation' GROUP BY 1", "claim": "The recommendation service emits no spans at all in the abnormal window, versus 725 server spans in the normal period."},
        {"kind": "metric", "sql": "SELECT date_trunc('minute', time) m, max(value) restarts FROM abnormal_metrics WHERE metric='k8s.container.restarts' AND attr_k8s_pod_name LIKE 'recommendation%' GROUP BY 1 ORDER BY 1", "claim": "Recommendation pod container restarts climb from 3 to 6 across the abnormal window, versus 0 in normal."},
        {"kind": "log", "sql": "SELECT min(time) t, count(*) n FROM abnormal_logs WHERE message LIKE '%hotel-reserv-recommendation%' AND message LIKE '%BackOff%' OR message LIKE '%executable file not found%'", "claim": "Kubelet events show the recommendation container failing to start (executable not found) and entering back-off restarts."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "recommendation",
      "to": "frontend",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%ecommend%' GROUP BY 1,2,3", "claim": "Frontend's GetRecommendations client calls error out (839 of 841), and its HTTP /recommendations server spans return 500."}
      ]
    }
  ]
}
